  2	class Rope {
  3	ghost var Contents: string;
  4	ghost var Repr: set<Rope>;
  5	
  6	var data: string;
  7	var weight: nat;
  8	var left: Rope?;
  9	var right: Rope?;
 10	
 11	ghost predicate Valid() 
 12	    reads this, Repr
 13	    ensures Valid() ==> this in Repr
 14	{
 15	    this in Repr &&
 16	    (left != null ==> 
 17	        left in Repr &&
 18	        left.Repr < Repr && this !in left.Repr &&
 19	        left.Valid() &&
 20	        (forall child :: child in left.Repr ==> child.weight <= weight)) &&
 21	    (right != null ==> 
 22	        right in Repr &&
 23	        right.Repr < Repr && this !in right.Repr &&
 24	        right.Valid()) &&
 25	    (left == null && right == null ==>
 26	        Repr == {this} &&
 27	        Contents == data &&
 28	        weight == |data| &&
 29	        data != "") &&
 30	    (left != null && right == null ==>
 31	        Repr == {this} + left.Repr &&
 32	        Contents == left.Contents &&
 33	        weight == |left.Contents| &&
 34	        data == "") &&
 35	    (left == null && right != null ==>
 36	        Repr == {this} + right.Repr &&
 37	        Contents == right.Contents &&
 38	        weight == 0 &&
 39	        data == "") &&
 40	    (left != null && right != null ==>
 41	        Repr == {this} + left.Repr + right.Repr &&
 42	        left.Repr !! right.Repr &&
 43	        Contents == left.Contents + right.Contents &&
 44	        weight == |left.Contents| &&
 45	        data == "") 
 46	}
 47	
 48	lemma contentSizeGtZero()
 49	    requires Valid()
 50	    ensures |Contents| > 0
 51	    decreases Repr
 52	{}
 53	
 54	function getWeightsOfAllRightChildren(): nat
 55	    reads right, Repr
 56	    requires Valid()
 57	    decreases Repr
 58	    ensures right != null
 59	        ==> getWeightsOfAllRightChildren() == |right.Contents|
 60	{
 61	    if right == null then 0
 62	    else right.weight + right.getWeightsOfAllRightChildren()
 63	} 
 64	
 65	function length(): nat
 66	    reads Repr
 67	    requires Valid()
 68	    ensures |Contents| == length()
 69	{
 70	    this.weight + getWeightsOfAllRightChildren()
 71	}
