 73	// constructor for creating a terminal node
 74	constructor Terminal(x: string)
 75	    requires x != ""
 76	    ensures Valid() && fresh(Repr)
 77	        && left == null && right == null
 78	        && data == x
 79	{ 
 80	    data := x;
 81	    weight := |x|;
 82	    left := null;
 83	    right := null;
 84	    Contents := x;
 85	    Repr := {this};
 86	}   
