 92	method report(i: nat, j: nat) returns (s: string)
 93	    requires 0 <= i <= j <= |this.Contents|
 94	    requires Valid()
 95	    ensures s == this.Contents[i..j]
 96	    decreases Repr
 97	{
 98	    if i == j {
 99	        s := "";
100	    } else {
101	        if this.left == null && this.right == null {
102	            s := data[i..j];
103	        } else {
104	            if (j <= this.weight) {
105	                var s' := this.left.report(i, j);
106	                s := s';
107	            } else if (this.weight <= i) {
108	                var s' := this.right.report(i - this.weight, j - this.weight);
109	                s := s';
110	            } else {
111	                // removing this assertion causes error
112	                assert i <= this.weight < j;
113	                var s1 := this.left.report(i, this.weight);
114	                var s2 := this.right.report(0, j - this.weight);
115	                s := s1 + s2;
116	            }
117	        }
118	    }
119	}
