128	method getCharAtIndex(index: nat) returns (c: char)
129	    requires Valid() && 0 <= index < |Contents|
130	    ensures c == Contents[index]
131	{
132	    var nTemp := this;
133	    var i := index;
134	    while (!nTemp.isTerminal()) 
135	        invariant nTemp != null;
136	        invariant nTemp.Valid()
137	        invariant 0 <= i < |nTemp.Contents|   
138	        invariant nTemp.Contents[i] == Contents[index] 
139	        decreases nTemp.Repr
140	    {
141	        if (i < nTemp.weight) {
142	            nTemp := nTemp.left;
143	        } else {
144	            i := i - nTemp.weight;
145	            nTemp := nTemp.right;
146	        }
147	    }
148	    // Have reached the terminal node with index i
149	    c := nTemp.data[i];
150	}
