152	static method concat(n1: Rope?, n2: Rope?) returns (n: Rope?) 
153	    requires (n1 != null) ==> n1.Valid()
154	    requires (n2 != null) ==> n2.Valid()
155	    requires (n1 != null && n2 != null) ==> (n1.Repr !! n2.Repr)
156	
157	    ensures (n1 != null || n2 != null) <==> n != null && n.Valid()
158	    ensures (n1 == null && n2 == null) <==> n == null
159	    ensures (n1 == null && n2 != null)
160	        ==> n == n2 && n != null && n.Valid() && n.Contents == n2.Contents
161	    ensures (n1 != null && n2 == null)
162	        ==> n == n1 && n != null && n.Valid() && n.Contents == n1.Contents
163	    ensures (n1 != null && n2 != null)
164	        ==> n != null && n.Valid()
165	            && n.left == n1 && n.right == n2
166	            && n.Contents == n1.Contents + n2.Contents
167	            && fresh(n.Repr - n1.Repr - n2.Repr)
168	{
169	    if (n1 == null) {
170	        n := n2;
171	    } else if (n2 == null) {
172	        n := n1;
173	    } else {
174	        n := new Rope.Terminal("placeholder");
175	        n.left := n1;
176	        n.right := n2;
177	        n.data := "";
178	
179	        var nTemp := n1;
180	        var w := 0;
181	        ghost var nodesTraversed : set<Rope> := {};
182	
183	        while (nTemp.right != null)
184	            invariant nTemp != null
185	            invariant nTemp.Valid()
186	            invariant forall node :: node in nodesTraversed ==> node.weight <= w
187	            invariant nodesTraversed == n1.Repr - nTemp.Repr
188	            invariant nTemp.right == null ==> w + nTemp.weight == |n1.Contents|
189	            invariant nTemp.right != null
190	                ==> w + nTemp.weight + |nTemp.right.Contents| == |n1.Contents| 
191	            decreases nTemp.Repr
192	        {
193	            w := w + nTemp.weight;
194	            assert w >= 0;
195	            if (nTemp.left != null) {
196	                nodesTraversed := nodesTraversed + nTemp.left.Repr + {nTemp};
197	            } else {
198	                nodesTraversed := nodesTraversed + {nTemp};
199	            }
200	            nTemp := nTemp.right;
201	        }
202	        w := w + nTemp.weight;
203	        if (nTemp.left != null) {
204	            nodesTraversed := nodesTraversed + nTemp.left.Repr + {nTemp};
205	        } else {
206	            nodesTraversed := nodesTraversed + {nTemp};
207	        }
208	        n.weight := w;
209	        n.Contents := n1.Contents + n2.Contents;
210	        n.Repr := {n} + n1.Repr + n2.Repr;
211	        } 
212	} 
