215	/**
216	    Dafny needs help to guess that in our definition, every rope must
217	    have non-empty Contents, otherwise it is represented by [null].
218	
219	    The lemma contentSizeGtZero(n) is thus important to prove the
220	    postcondition of this method, in the two places where the lemma is
221	    invoked.
222	*/
223	static method split(n: Rope, index: nat) returns (n1: Rope?, n2: Rope?) 
224	    requires n.Valid() && 0 <= index <= |n.Contents|
225	    ensures index == 0
226	        ==> n1 == null && n2 != null && n2.Valid()
227	            && n2.Contents == n.Contents && fresh(n2.Repr - n.Repr)
228	    ensures index == |n.Contents|
229	        ==> n2 == null && n1 != null && n1.Valid()
230	            && n1.Contents == n.Contents && fresh(n1.Repr - n.Repr)
231	    ensures 0 < index < |n.Contents|
232	        ==> n1 != null && n1.Valid() && n2 != null && n2.Valid()
233	            && n1.Contents == n.Contents[..index]
234	            && n2.Contents == n.Contents[index..]
235	            && n1.Repr !! n2.Repr
236	            && fresh(n1.Repr - n.Repr) && fresh(n2.Repr - n.Repr)
237	    decreases n.Repr
238	{
239	    if (index == 0) {
240	        n1 := null;
241	        n2 := n;
242	        n.contentSizeGtZero();
243	        // assert index != |n.Contents|;
244	    } else if (index < n.weight) {
245	        if (n.left != null) {
246	            var s1, s2 := split(n.left, index);
247	            n1 := s1;
248	            n2 := concat(s2, n.right);
249	        } else {
250	            // terminal node
251	            assert n.isTerminal();
252	            if (index == 0) {
253	                n1 := null;
254	                n2 := n;
255	            } else {
256	                n1 := new Rope.Terminal(n.data[..index]);
257	                n2 := new Rope.Terminal(n.data[index..]);
258	            }
259	        }
260	    } else if (index > n.weight) {
261	        var s1, s2 := split(n.right, index - n.weight);
262	        n1 := concat(n.left, s1);
263	        n2 := s2;
264	    } else {
265	        // since [n.weight == index != 0], it means that [n] cannot be a
266	        // non-terminal node with [left == null].
267	        if (n.left != null && n.right == null) {
268	            n1 := n.left;
269	            n2 := null;
270	        } else if (n.left != null && n.right != null) {
271	            n.right.contentSizeGtZero();
272	            // assert index != |n.Contents|;
273	            n1 := n.left;
274	            n2 := n.right;
275	        } else {
276	            assert n.left == null && n.right == null;
277	            n1 := n;
278	            n2 := null;
279	        }
280	    }
281	}
282	
283	static method insert(n1: Rope, n2: Rope, index: nat) returns (n: Rope)
284	    requires n1.Valid() && n2.Valid() && n1.Repr !! n2.Repr
285	    requires 0 <= index < |n1.Contents|
286	    ensures n.Valid()
287	        && n.Contents ==
288	            n1.Contents[..index] + n2.Contents + n1.Contents[index..]
289	        && fresh(n.Repr - n1.Repr - n2.Repr)
290	{
291	    var n1BeforeIndex, n1AfterIndex := split(n1, index);
292	    var firstPart := concat(n1BeforeIndex, n2);
293	    n := concat(firstPart, n1AfterIndex);
294	}
295	
296	static method delete(n: Rope, i: nat, j: nat) returns (m: Rope?)
297	    requires n.Valid()
298	    requires 0 <= i < j <= |n.Contents|
299	    ensures (i == 0 && j == |n.Contents|) <==> m == null
300	    ensures m != null ==>
301	        m.Valid() &&
302	        m.Contents == n.Contents[..i] + n.Contents[j..] &&
303	        fresh(m.Repr - n.Repr)
304	{
305	    var l1, l2 := split(n, i);
306	    var r1, r2 := split(l2, j - i);
307	    m := concat(l1, r2);
308	}
309	
310	static method substring(n: Rope, i: nat, j: nat) returns (m: Rope?)
311	    requires n.Valid()
312	    requires 0 <= i < j <= |n.Contents|
313	    ensures (i == j) <==> m == null
314	    ensures m != null ==>
315	        m.Valid() &&
316	        m.Contents == n.Contents[i..j] &&
317	        fresh(m.Repr - n.Repr)
318	{
319	    var l1, l2 := split(n, i);
320	    var r1, r2 := split(l2, j - i);
321	    m := r1;
322	}
323	
324	}
325	// End of Rope Class
326	}
327	// End of Rope Module

